/* Generated by `npm run icons` from icon-sources.json; edit the manifest, not this file. */
import { render } from '@testing-library/react';
import type { ComponentType } from 'react';
import { describe, expect, it } from 'vitest';

import * as glyph from '../src/index.js';

type IconComponent = ComponentType<{ size?: 'lg' | 'md' | 'sm' }>;

const NAMES =
    `add arrow-inbound arrow-outbound bell braces check chevron-down chevron-left chevron-right chevron-up clear-all close code collapse-all collection color-mode compare connect connection console copy corner-radius dash delete disconnect doc duplicate edit environment error export external-link eye eye-closed file file-code filter fold folder format globe grip-vertical headers http import info keepalive key layout-horizontal layout-vertical link loading markdown menu message more-horizontal more-vertical origin-azure origin-bitbucket origin-github origin-gitlab origin-local origin-remote panel-maximize pin pinned preview record refresh rename save schema search send settings sidebar-left sliders split-horizontal split-vertical unfold warning window-close window-maximize window-minimize window-restore workspace wrap-text wrap-text-off zoom-in zoom-out`.split(
        ' ',
    );

function componentOf(name: string): string {
    return (
        name
            .split('-')
            .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
            .join('') + 'Icon'
    );
}

describe('the generated icons', () => {
    for (const name of NAMES) {
        const Icon = glyph[componentOf(name) as keyof typeof glyph] as IconComponent;

        it(`draws the ${name} icon hidden on every size of the scale`, () => {
            for (const size of ['sm', 'md', 'lg'] as const) {
                const { container, unmount } = render(<Icon size={size} />);
                const svg = container.querySelector('svg');

                expect(svg?.getAttribute('aria-hidden')).toBe('true');
                expect(svg?.getAttribute('data-part')).toBe('icon');
                expect(svg?.getAttribute('height')).toBe(
                    ({ lg: '24', md: '16', sm: '14' } as const)[size],
                );
                expect(svg?.querySelector('path')).not.toBeNull();
                unmount();
            }
        });
    }
});
